const loadFiles = async (files: FileList | File[], sessionId: string) => {
  for (const file of Array.from(files)) {
    if (file.size > 25 * 1024 * 1024) throw new Error('Attachments must be smaller than 25 MB.');
    const data: string = await new Promise((resolve, reject) => { const r = new FileReader(); r.onload = () => resolve(String(r.result).split(',')[1]); r.onerror = reject; r.readAsDataURL(file); });
    await api('attach', { id: sessionId, data, name: file.name || 'Pasted image.png' });
  }
};

